import{_ as t,o as r,c as n,ac as o}from"./chunks/framework.B-3EzaJq.js";const l=JSON.parse('{"title":"中国共产党第十三届中央委员会第一次全体会议公报","description":"","frontmatter":{"prev":{"text":"十三届一中全会简介","link":"./"},"next":{"text":"十三届二中全会简介","link":"../2/"}},"headers":[],"relativePath":"13/1/中国共产党第十三届中央委员会第一次全体会议公报.md","filePath":"13/1/中国共产党第十三届中央委员会第一次全体会议公报.md"}'),s={name:"13/1/中国共产党第十三届中央委员会第一次全体会议公报.md"};function _(e,p,g,a,i,c){return r(),n("div",null,[...p[0]||(p[0]=[o('<h1 id="中国共产党第十三届中央委员会第一次全体会议公报" tabindex="-1">中国共产党第十三届中央委员会第一次全体会议公报 <a class="header-anchor" href="#中国共产党第十三届中央委员会第一次全体会议公报" aria-label="Permalink to &quot;中国共产党第十三届中央委员会第一次全体会议公报&quot;">​</a></h1><p><em>（1987年11月2日）</em></p><p>  中国共产党第十三届中央委员会第一次全体会议，1987年11月2日在北京举行。</p><p>  赵紫阳同志主持了会议。到会的中央委员173人，中央候补委员106人。中央顾问委员会委员、中央纪律检查委员会委员列席了会议。</p><p>  全会选举产生了中央政治局委员、候补委员，中央政治局常务委员会委员，中央委员会总书记；</p><p>  根据中央政治局常务委员会的提名，通过了中央书记处书记和候补书记；</p><p>  决定了中央军事委员会主席、第一副主席、常务副主席。</p><p>  名单如下：</p><p>  <strong>一、中央政治局委员、候补委员</strong></p><p>  <strong>中央政治局委员</strong> （按姓氏笔划为序）：</p><p>  万里、田纪云、乔石、江泽民、李鹏、李铁映、李瑞环、李锡铭、杨汝岱、杨尚昆、吴学谦、宋平、赵紫阳、胡启立、胡耀邦、姚依林、秦基伟</p><p>  <strong>中央政治局候补委员</strong> ：丁关根</p><p>  <strong>二、中央政治局常务委员会委员</strong></p><p>  赵紫阳、李鹏、乔石、胡启立、姚依林</p><p>  <strong>三、中央委员会总书记</strong> ：赵紫阳</p><p>  <strong>四、中央书记处书记、候补书记</strong></p><p>  <strong>书记</strong> ：胡启立、乔石、芮杏文、阎明复</p><p>  <strong>候补书记</strong> ：温家宝</p><p>  <strong>五、中央军事委员会主席、第一副主席、常务副主席</strong></p><p>  <strong>主席</strong> ：邓小平</p><p>  <strong>第一副主席</strong> ：赵紫阳</p><p>  <strong>常务副主席</strong> ：杨尚昆</p><p>  全会批准了中央顾问委员会第一次全体会议选举产生的主任、副主任和常务委员会委员人选。</p><p>  名单如下：</p><p>  <strong>中央顾问委员会</strong></p><p> &amp;emsp<strong>主任</strong> ：陈云</p><p>  <strong>副主任</strong> ：薄一波、宋任穷</p><p>  <strong>常务委员会委员</strong> （按姓氏笔划为序）：</p><p>  王平、王首道、伍修权、刘澜涛、江华、李一氓、李德生、杨得志、肖克、余秋里、宋任穷、宋时轮、张劲夫、张爱萍、陆定一、陈云、陈丕显、陈锡联、胡乔木、段君毅、耿飚、姬鹏飞、黄华、黄镇、康世恩、程子华、薄一波</p><p>  全会批准了中央纪律检查委员会第一次全体会议选举产生的书记、副书记和常务委员会委员人选。</p><p>  名单如下：</p><p>  <strong>中央纪律检查委员会</strong></p><p> &amp;emsp<strong>书记</strong> ：乔石</p><p>  <strong>副书记</strong> ：陈作霖、李正亭、肖洪达</p><p>  <strong>常务委员会委员</strong> （按姓氏笔划为序）：</p><p>  王德瑛、乔石、刘丽英、李正亭、肖洪达、陈作霖、郭林祥、傅杰</p>',36)])])}const d=t(s,[["render",_]]);export{l as __pageData,d as default};
